import type { EmbeddedPanel } from "./embedded";

// The module that `bun run build:panel` writes over src/web/embedded.ts. JSON
// string literals are valid JavaScript, so the panel text is embedded exactly.
export function renderEmbeddedModule(panel: EmbeddedPanel): string {
  return [
    "// Generated by scripts/build-panel.ts. Do not edit by hand.",
    "export type EmbeddedPanel = { html: string; css: string; script: string };",
    `export const embeddedPanel: EmbeddedPanel | undefined = ${JSON.stringify(panel)};`,
    "",
  ].join("\n");
}
